input.command:
mkdir -p src/inngest src/app/api/inngest && cat > src/inngest/client.ts <<'EOF'
import { Inngest } from "inngest";

export const inngest = new Inngest({ id: "notely" });
EOF
cat > src/inngest/functions.ts <<'EOF'
import { inngest } from "./client";

export const USER_CREATED_EVENT = "notely/user.created";

export type UserCreatedData = { userId: string; email: string; name: string };

// Sleeps 10 minutes, then logs a reminder. Inngest retries the function
// (with backoff) if the step throws; the sleep is not repeated on retry.
export const userReminder = inngest.createFunction(
  { id: "user-reminder", retries: 5, triggers: [{ event: USER_CREATED_EVENT }] },
  async ({ event, step }) => {
    const data = event.data as UserCreatedData;
    await step.sleep("wait-10-minutes", "10m");
    await step.run("log-reminder", () => {
      console.log(`[reminder] ${data.name} <${data.email}> (user ${data.userId}) joined Notely 10 minutes ago`);
    });
  },
);
EOF
cat > src/app/api/inngest/route.ts <<'EOF'
import { serve } from "inngest/next";
import { inngest } from "@/inngest/client";
import { userReminder } from "@/inngest/functions";

export const { GET, POST, PUT } = serve({ client: inngest, functions: [userReminder] });
EOF
cat >> src/lib/users.ts <<'EOF'

export async function createUser(input: { email: string; name: string }): Promise<User> {
  const user: User = {
    id: String(users.length + 1),
    email: input.email,
    name: input.name,
    createdAt: new Date().toISOString().slice(0, 10),
  };
  users.push(user);

  // Schedule the reminder job. A queueing failure must not fail user creation.
  try {
    await inngest.send({
      name: USER_CREATED_EVENT,
      data: { userId: user.id, email: user.email, name: user.name } satisfies UserCreatedData,
    });
  } catch (err) {
    console.error("Failed to schedule reminder job for user", user.id, err);
  }
  return user;
}
EOF
sed -i '' '1i\
import { inngest } from "@/inngest/client";\
import { USER_CREATED_EVENT, type UserCreatedData } from "@/inngest/functions";\

' src/lib/users.ts
cat > .env.example <<'EOF'
# Inngest (https://www.inngest.com). Leave both unset for local dev with the
# Inngest dev server: npx inngest-cli@latest dev -u http://localhost:3000/api/inngest
INNGEST_EVENT_KEY=placeholder-event-key
INNGEST_SIGNING_KEY=signkey-prod-placeholder
# Set to 1 to force dev mode locally
# INNGEST_DEV=1
EOF
printf '!.env.example\n' >> .gitignore
npx tsc --noEmit && npx eslint src && head -5 src/lib/users.ts

